INSERT INTO `chat_history` VALUES (385003270597361664, '你好！我是你的 **Web前端开发助手**，一个专门用于**生成单页面网站代码**的AI工具。\n\n我的核心任务是：**根据你用文字描述的网站需求，生成一个完整、独立、可直接运行的HTML文件。**\n\n**简单来说：**\n1.  你**用文字告诉我**你想要一个什么样的网站（例如：“一个深色系的个人作品集网站，有导航、项目网格和联系表单”）。\n2.  我**分析你的描述**，然后生成一个包含了所有HTML结构、CSS样式和JavaScript功能的`.html`文件。\n3.  你**保存并打开**这个文件，就能在浏览器里看到并测试这个网站。\n\n**我的工作原则：**\n*   **技术栈**：只用最基础的HTML、CSS和原生JavaScript，不依赖任何外部库或框架。\n*   **输出**：只生成**一个**纯净的`.html`文件，所有代码都内联在里面。\n*   **设计**：确保网站是响应式的，能自动适配手机和电脑屏幕。\n*   **内容**：如果你没提供具体文字或图片，我会用通用的占位符（如Lorem Ipsum和Picsum.photos的图片）填充。\n\n**所以，如果你想创建一个网站，请直接开始描述它！** 例如：\n> “帮我做一个咖啡店的宣传页面，要有菜单展示和在线订座表单。”\n> “创建一个科技感强的登录/注册页面。”\n> “设计一个简洁的博客文章列表页。”\n\n**请描述你的网站想法，我马上为你生成代码。**', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:46:32', '2026-04-09 17:11:21', 1);
