INSERT INTO `chat_history` VALUES (385004007582638080, '你好！我是你的 **Web前端开发代码生成器**。\n\n**我是谁：**\n我是一个专门用于**生成单页面网站完整代码**的AI工具。我的知识库专注于HTML、CSS和原生JavaScript。\n\n**我能做什么：**\n根据你的**文字描述**，生成一个**可直接使用的单页面网站**。\n\n**具体来说：**\n1.  **输入**：你提供网站的文字描述（比如“一个宠物医院的官网，有服务介绍、医生团队和预约表单”）。\n2.  **处理**：我分析你的需求，设计结构，编写代码。\n3.  **输出**：我返回一个**完整的、独立的 `.html` 文件**，包含：\n    *   所有HTML结构\n    *   所有CSS样式（内联在`<style>`标签中）\n    *   所有JavaScript功能（内联在`<script>`标签中）\n4.  **结果**：你保存这个文件，用浏览器打开，就能看到一个功能完整的响应式网站。\n\n**我的特点：**\n*   **纯原生**：只用HTML、CSS、JS，不用任何框架或库。\n*   **单文件**：所有代码都在一个HTML文件里，方便分享和测试。\n*   **响应式**：自动适配手机和电脑。\n*   **可交互**：用原生JS实现轮播、标签页、表单验证等常见功能。\n\n**举个例子：**\n你对我说：“**帮我做一个餐厅菜单页面，有分类标签和菜品图片网格。**”\n\n我就会生成一个包含以下功能的HTML文件：\n- 响应式导航\n- 菜品分类标签（点击切换）\n- 菜品卡片网格（带图片和价格）\n- 适配移动端\n\n**现在，请告诉我你想创建什么网站？** 用一句话描述即可开始。', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:49:28', '2026-04-09 17:11:21', 1);
INSERT INTO `chat_history` VALUES (385004029221052416, '你好！我是你的 **Web 前端开发专家**，一个专门用于**生成单页面网站代码**的AI工具。\n\n**我能做什么：**\n根据你用文字描述的网站需求，我能够生成一个**完整、独立、可直接运行的单页面网站**的HTML代码。具体来说：\n\n1.  **技术实现**：使用纯 **HTML、CSS 和原生 JavaScript** 编写代码，不依赖任何外部库或框架（如Bootstrap、jQuery、React等）。\n2.  **完整交付**：将所有代码（结构、样式、逻辑）整合到**一个 `.html` 文件**中，你保存后即可在浏览器中打开使用。\n3.  **响应式设计**：确保网站在桌面、平板和手机等不同设备上都能良好显示。\n4.  **交互功能**：用原生JavaScript实现常见的交互功能，如图片轮播、标签页切换、表单验证、模态框等。\n5.  **内容填充**：如果你没有提供具体的文本或图片，我会使用合理的占位内容（如Lorem Ipsum文本和来自Picsum.photos的示例图片）来填充，使页面结构完整。\n6.  **代码质量**：生成结构清晰、注释得当、易于阅读和维护的代码。\n\n**我的工作流程：**\n1.  **你描述**：用文字告诉我你想要创建的网站。例如：“一个深色系的个人简历网站，包含关于我、技能、项目展示和联系方式。”\n2.  **我思考**：我会分析你的需求，规划页面结构、样式和交互。\n3.  **我生成**：我会输出一个完整的HTML代码块，里面包含了实现这个网站所需的一切。\n\n**举例说明：**\n如果你对我说：“帮我做一个宠物店的宣传页面，要有服务介绍、宠物照片展示和预约表单。”\n我会为你生成一个包含以下部分的HTML文件：\n-   响应式导航栏\n-   吸引人的横幅（Hero Section）\n-   服务介绍卡片区域\n-   宠物照片画廊（可能是网格或轮播形式）\n-   预约表单\n-   页脚\n-   以及实现这些功能的所有CSS样式和JavaScript代码。\n\n**现在，请告诉我你想创建一个什么样的网站，我们马上开始！**', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:49:33', '2026-04-09 17:11:21', 1);
