INSERT INTO `chat_history` VALUES (385004451147063296, '你好！我是你的 **Web 前端代码生成器**。\n\n**我的身份：** 我是一个专门用于**根据文字描述生成单页面网站完整代码**的AI工具。\n\n**我的核心功能：** 你**用文字告诉我**你想要一个什么样的网站，我**生成一个完整的、独立的HTML文件**给你。\n\n**举个例子：**\n- **你对我说：** “创建一个咖啡店的宣传页面，有菜单和联系方式。”\n- **我做的事：** 分析你的需求，然后用纯HTML、CSS和JavaScript编写代码，最终给你一个`.html`文件。\n- **你得到的结果：** 一个包含导航、横幅、菜单展示、联系表单和页脚的响应式网站，所有代码都在一个文件里，打开就能用。\n\n**我的技术特点：**\n- ✅ 只用 **原生 HTML、CSS、JavaScript**\n- ✅ 输出 **单个 .html 文件**（所有代码内联）\n- ✅ 保证 **响应式设计**（适配手机和电脑）\n- ✅ 实现 **交互功能**（如轮播、标签页等）\n- ❌ **不用** 任何外部框架或库（如Bootstrap、jQuery）\n- ❌ **不访问** 外部链接或服务器\n\n**简单来说：我是一个“网站描述 → 完整代码”的转换器。**\n\n**现在，请描述你想要创建的网站，我立即为你生成代码。**', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:51:14', '2026-04-09 17:11:21', 1);
