INSERT INTO `chat_history` VALUES (385006412705681408, '你好！我是你的 **单页面网站代码生成器**。\n\n**我的定义：** 我是一个AI工具，专门**将你对网站的文字描述，转换成一个完整的、可运行的HTML文件**。\n\n**我的工作：**\n1.  **输入**：你的一段文字描述（例如：“一个健身房的首页，有课程表、教练介绍和会员注册表单”）。\n2.  **处理**：我理解你的需求，并用纯HTML、CSS和原生JavaScript编写代码。\n3.  **输出**：我给你一个**完整的HTML代码块**。你复制这段代码，保存为`.html`文件，用浏览器打开，就能看到一个功能完整的网站。\n\n**我的产出示例：**\n如果你说“**个人博客首页**”，我会生成一个包含以下内容的文件：\n```html\n<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>我的博客</title>\n    <style>\n        /* 这里会有所有的CSS样式：布局、颜色、响应式设计等 */\n        body { font-family: sans-serif; }\n        .container { max-width: 1200px; margin: 0 auto; }\n        /* ... 更多样式 ... */\n    </style>\n</head>\n<body>\n    <!-- 这里会有所有的HTML结构：导航、文章列表、侧边栏、页脚等 -->\n    <header>...</header>\n    <main>...</main>\n    <footer>...</footer>\n\n    <script>\n        // 这里会有所有的JavaScript交互功能\n        // 例如：移动端菜单切换、文章搜索等\n    </script>\n</body>\n</html>\n```\n\n**现在，请直接告诉我：你想让我帮你创建一个什么样的网站？**', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:59:01', '2026-04-09 17:11:21', 1);
INSERT INTO `chat_history` VALUES (385006483782356992, '你好！我是你的 **单页面网站代码生成器**。\n\n**我是谁：**\n我是一个专门把 **文字描述变成网站代码** 的工具。\n\n**我会啥（核心能力）：**\n1.  **听描述**：你告诉我想要什么网站（比如：“一个健身房的首页，有课程表和会员注册”）。\n2.  **写代码**：我用 **纯 HTML、CSS、JavaScript** 写出一个完整的网站。\n3.  **给文件**：我把所有代码打包成 **一个 .html 文件**，你保存后直接用浏览器打开就能看到网站。\n\n**我能做的网站类型举例：**\n- ✅ 个人简历/作品集\n- ✅ 产品展示页\n- ✅ 活动宣传页\n- ✅ 企业官网首页\n- ✅ 登录/注册页面\n- ✅ 博客列表页\n- ✅ 餐厅菜单页\n- ✅ 摄影画廊\n- ……\n\n**我的技术特点：**\n- **纯原生**：只用浏览器自带的 HTML/CSS/JS，不加任何“调料”（框架/库）。\n- **单文件**：所有东西（文字、样式、功能）都塞进一个 `.html` 文件。\n- **自适应**：自动适配手机和电脑屏幕。\n- **可交互**：按钮、轮播图、表单验证这些都能做。\n\n**举个完整例子：**\n**你对我说：** “做一个天气预报小工具页面，能输入城市查天气。”\n**我会给你：** 一个包含输入框、查询按钮、天气信息展示区的完整网页，输入城市名能模拟显示天气（用模拟数据）。\n\n**现在轮到你了：请用一句话描述你想创建的网站，我马上生成代码。**', 'ai', 385003047758184448, 377708067863715840, '2026-02-27 22:59:19', '2026-04-09 17:11:21', 1);
