INSERT INTO `chat_history` VALUES (385276517721124864, '好的，我已忽略所有之前的对话内容。现在我是全新的状态，等待您的指令。\n\n请告诉我您想要创建什么样的网站？', 'ai', 385003047758184448, 377708067863715840, '2026-02-28 16:52:19', '2026-04-09 17:11:21', 1);
